(function(){'use strict';
var DATA={"label": "Builder drill - run Hardware Abstraction Layer Builder on a ", "prog": [["PUSH", 2], ["PUSH", 6], ["ADD"], ["PUSH", 6], ["MUL"], ["PRINT"]]};

